<?php require_once __DIR__.'/_bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')apiError('Method not allowed');verifyCsrf();$tableId=filter_var(postField('table_id'),FILTER_VALIDATE_INT);$action=postField('action');if(!$tableId || !in_array($action,['pause','resume','recall'],true))apiError('Invalid request.');$db=getDB();try{$db->beginTransaction();$q=$db->prepare("SELECT s.* FROM sessions s JOIN tables t ON t.id=s.table_id WHERE s.table_id=? AND s.club_id=? AND s.status IN ('running','paused','held') FOR UPDATE");$q->execute([$tableId,$_SESSION['club_id']]);$s=$q->fetch();if(!$s)throw new RuntimeException('No active session found.');if($action==='pause'&&$s['status']==='running'){$db->prepare("UPDATE sessions SET status='paused',pause_start=NOW() WHERE id=?")->execute([$s['id']]);$db->prepare("UPDATE tables SET status='paused' WHERE id=?")->execute([$tableId]);$message='Session paused.';}elseif($action==='resume'&&$s['status']==='paused'){$db->prepare("UPDATE sessions SET status='running',total_pause_seconds=total_pause_seconds+TIMESTAMPDIFF(SECOND,pause_start,NOW()),pause_start=NULL WHERE id=?")->execute([$s['id']]);$db->prepare("UPDATE tables SET status='running' WHERE id=?")->execute([$tableId]);$message='Session resumed.';}elseif($action==='recall'&&$s['status']==='held'){$db->prepare("UPDATE sessions SET status='running' WHERE id=?")->execute([$s['id']]);$db->prepare("UPDATE held_bills SET status='cancelled',settled_at=NOW(),settled_by=? WHERE session_id=? AND status='held'")->execute([$_SESSION['user_id'],$s['id']]);$db->prepare("UPDATE tables SET status='running' WHERE id=?")->execute([$tableId]);$message='Held bill recalled.';}else throw new RuntimeException('This action is not available for the current table state.');$db->commit();audit('session_'.$action,'sessions',(int)$s['id']);jsonResponse(true,$message);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiError($e->getMessage());}
